const cursorTs = msg.metadata.source.timestamp;
const bridgePattern = /\[(?:wasos|cim|parat_bridge)(?::|])/;

msg.payload = msg.payload.filter(entry => {
    if (entry.timeCreated <= cursorTs) return false;
    if (entry.text && bridgePattern.test(entry.text)) return false;
    if (entry.loggedByFullName && bridgePattern.test(entry.loggedByFullName)) return false;
    return true;
});

if (msg.payload.length === 0) return null;

global.set(
    `parat_bridge.connections.${msg.metadata.connection_name}.clients.${msg.metadata.source.identifier}.timestamp`,
    msg.payload[msg.payload.length - 1].timeCreated
);

return msg;

if (!msg.payload || msg.payload.length === 0) return null;

msg.payload.sort((a, b) => a.timeCreated - b.timeCreated);
return msg;
